import { IfcWasmConverterLoader } from "./ifcWasmConverterLoader";
import { WasmModule } from "./wasmModuleInterface";

export class IfcConverter {
    private module?: WasmModule;
    private metaDataGlobal?: { [key: string]: any };
    private handleGLTFclb?: (glbContent: string) => Promise<void>;
    private handleMetaDataClb?: (metaData: { [key: string]: any }) => Promise<void>;
    private GLTFs: string[] = [];

    private constructor() { }

    private async init(inputOptions: string = IfcConverter.getDefaultInputOptions()) {
        //TODO should expose url to set it from outside
        this.module = await IfcWasmConverterLoader.getModule('remote');
        this.module!.setInputOptions(inputOptions);
        this.module!.setGltfChunkDoneCallback(this.gltfChunkDoneCallback.bind(this));
        this.module!.setMetaDataCompleteCallback(this.metaDataCompleteCallback.bind(this));
    }
    static async create(inputOptions: string = IfcConverter.getDefaultInputOptions()): Promise<IfcConverter> {
        let ifcConverter = new IfcConverter()
        await ifcConverter.init(inputOptions);
        return ifcConverter;
    }

    loadModel(data: string, loadOptions: any = IfcConverter.getDefaultLoadOptions()) {
        this.module!.loadModel(data, loadOptions);
    }
    registerProgressCallback(progressCallback: (progress: number) => void) {
        this.module!.setProgressCallback(progressCallback);
    }
    registerProgressTextCallback(progressTextCallback: (progressText: string) => void) {
        this.module!.setProgressTextCallback(progressTextCallback);
    }
    registerGltfChunkDoneCallback(handleGLTFclb: (gltf: string) => Promise<void>) {
        this.handleGLTFclb = handleGLTFclb;
    }
    registerMetaDataCompleteCallback(handleMetaDataClb: (metaData: { [key: string]: any }) => Promise<void>) {
        this.handleMetaDataClb = handleMetaDataClb;
    }
    registerGltfCompleteCallback(gltfCompleteCallback: () => void) {
        this.module!.setGltfCompleteCallback(gltfCompleteCallback);
    }

    static getDefaultInputOptions() {
        const inputOptions = {
            "inputParameters": {
                "exportPropertySets": "yes",
                "exportIfcPropertyTypes": "yes",
                "exportIfcValueTypes": "yes",
                "exportPolylines": "yes",
                "excludeGeometryForIfcTypes": ["IfcOpeningElement"],
                "exportGeometryOnlyForIfcTypes": [""],
                "excludeGUIDs": [""],
                "exportOnlyGUIDs": [""],
                "centerModelAtOrigin": "yes",
                "ignoreProfileRadius": "yes",
                "enableGltfCompression": "yes",
                "enableGltfQuantization": "no",
                "exportNormals": "no",
                "numPointsPerCircle": 18,
                "licenceKey": "",
                // JSON above is copied from default input config file. Changes applied here:
                "loadingPriorityTypes": ["IFCWALL", "IFCSLAB", "IFCWINDOW", "IFCROOF", "IFCFURNISHINGELEMENT", "IFCAIRTERMINAL"]//[ "IfcOpeningElement" ],
            }
        };

        const inputOptionsString = JSON.stringify(inputOptions);
        return inputOptionsString;
    }

    static getDefaultLoadOptions() {
        const loadOptions = {
            "maxFileSizeInMegaBytes": 15
        };
        return loadOptions;
    }

    async metaDataCompleteCallback() {
        console.log("metaDataCompleteCallback");
        try {
            const uint8Array = await this.module!.getMetaData();

            const decoder = new TextDecoder();
            const metaStr = decoder.decode(uint8Array);
            //console.log(metaStr);

            this.metaDataGlobal = await JSON.parse(metaStr);
            if (this.metaDataGlobal!.metaObjects != null) {
                console.log("loading " + this.metaDataGlobal!.metaObjects.length + " meta objects");
            }
        }
        catch (e) {
            console.log("getMetaData failed: " + e)
        }
        if (this.handleMetaDataClb)
            await this.handleMetaDataClb(this.metaDataGlobal!);
    }

    async gltfChunkDoneCallback() {
        console.log("GltfChunkDoneCallback");
        try {
            const glbContent = await this.module!.getGeometry();
            await this.module!.clearFileContent();
            this.GLTFs.push(glbContent);
            if (glbContent.length > 0) {
                if (this.handleGLTFclb)
                    await this.handleGLTFclb(glbContent);
            }
        }
        catch (e) {
            console.log("getGeometry failed: " + e)
        }
    }
}
