//import package json
import packageJSON from "./../package.json";
const cdnUrl = `https://cdn.jsdelivr.net/npm/@creooxag/cxconverter@${packageJSON.version}/dist/`;

import IfcDbWasmLocal from "./cpp/ifcdb.js";

const defaultUrlPrefix = "./";

export class IfcWasmConverterLoader {
  static instance: IfcWasmConverterLoader;
  private module: any;
  private constructor() { }

  static async getInstance(userUrlPrefix: string = 'remote'): Promise<IfcWasmConverterLoader> {
    let urlPrefix = defaultUrlPrefix;
    if (userUrlPrefix) {
      urlPrefix = userUrlPrefix == 'remote' ? cdnUrl : userUrlPrefix;
    }

    if (!IfcWasmConverterLoader.instance) {
      IfcWasmConverterLoader.instance = new IfcWasmConverterLoader();
      const Module = {
        locateFile: function (path: string) {
          const fullPath = urlPrefix + path;
          if (path.endsWith(".wasm")) {
            console.log(`Loading wasm file from ${fullPath}`);
            return fullPath;
          }
          return path;
        }
      };
      try {
        IfcWasmConverterLoader.instance.module = await IfcDbWasmLocal(Module);

      } catch (error) {
        console.error('Error on wasm import:', error);
      }
    }

    return IfcWasmConverterLoader.instance;
  }
  static async getModule(userUrlPrefix?: string) {
    return (await IfcWasmConverterLoader.getInstance(userUrlPrefix)).module;
  }
}
